// Constant String Literal (points to read-only memory)
const char *name = "String Constant";

// Literal assigned to a non-const pointer (discouraged)
char *p = "Fixed Text";

// Array initialized from a literal (data is copied/writable)
char buffer[] = "Message";

// Size includes the null terminator '\0'
size_t length = sizeof("Message"); // length == 8

// Wide character string literal
const wchar_t *w_ptr = L"Unicode Data";
